window.CCAR_Q = (window.CCAR_Q || []).concat([
{"id":"D3-01","d":3,"t":"s","q":"Scenario: Claude Code in a monorepo. The repository holds a web frontend, a payments service and shared libraries. Coding conventions apply everywhere, but the payments service also has strict rules (no floating-point money, mandatory audit logging) that would only confuse work on the frontend. Where should these instructions go?","o":["Put everything in one root CLAUDE.md, so that every session sees all of the rules at all times, in every folder","Keep shared conventions in the root CLAUDE.md and the payments rules in a CLAUDE.md in the payments directory","Put everything in each developer's personal ~/.claude/CLAUDE.md, so that the rules are never committed anywhere","Document the payments rules in a README, which Claude reads automatically at the start of every session"],"a":[1],"x":["every session pays the context cost of rules that are irrelevant to most tasks, and the important ones are diluted.","shared conventions apply everywhere while specialised rules load only when relevant, which keeps context focused.","personal files are not shared, so the team would drift and new members would miss the rules.","a README is not loaded automatically as instructions; CLAUDE.md is the mechanism for that."],"e":"Layer CLAUDE.md files: shared rules at the root, specialised rules in the directory where they apply."},
{"id":"D3-02","d":3,"t":"s","q":"Scenario: Claude Code on a team. The repository's CLAUDE.md says 'always run prettier after editing a file', yet formatting differences keep appearing in pull requests. The team wants formatting to be applied on every edit, without exception. What is the best change?","o":["Move the instruction to the top of CLAUDE.md and write it in capital letters so that it stands out","Configure a PostToolUse hook on the file-editing tools that runs the formatter after each edit","Add the instruction to each slash command that developers use, so that every workflow mentions formatting","Ask developers to remind Claude to format the files at the end of each session before they commit"],"a":[1],"x":["emphasis improves the odds but it is still an instruction the model may not follow.","hooks run deterministically after matching tool calls, so formatting no longer depends on the model remembering.","this covers only sessions that use those commands and still depends on the model's compliance.","a manual reminder is the least reliable option and creates work for every developer."],"e":"Use hooks for actions that must happen every time; CLAUDE.md is guidance, not enforcement."},
{"id":"D3-03","d":3,"t":"s","q":"Scenario: Claude Code settings. A team wants to share a set of permission rules (allowed test commands, denied destructive commands) through the repository, while individual developers add personal experiments that must not be committed. Which arrangement fits?","o":["Put everything in ~/.claude/settings.json on each developer's machine, and share the content by chat message","Put everything in .claude/settings.json and ask developers not to change the shared rules for personal use","Share rules in the committed .claude/settings.json; keep personal overrides in .claude/settings.local.json","Use CLAUDE.md for the permission rules, because Claude reads that file before it uses any of the tools"],"a":[2],"x":["user-level settings are not shared, so the team has no common rules.","personal experiments would end up in the shared file or violate the agreement, and the shared file becomes a point of conflict.","project settings are shared through version control, and local settings stay on the machine for personal changes.","CLAUDE.md holds instructions, not enforceable permission rules."],"e":"Use project settings for shared rules and local settings for personal overrides."},
{"id":"D3-04","d":3,"t":"s","q":"Scenario: Claude Code workflows. A team has a 40-step release-notes procedure that is needed only a few times per month. Putting it in CLAUDE.md made the file long, and sessions for unrelated work became slower and less focused. What is the best way to keep the procedure available?","o":["Package it as a skill with a clear description, so that it is loaded only when the task calls for it","Keep it in CLAUDE.md but shorten the wording of every other instruction to make room for the procedure","Move it to a comment in the changelog file, and expect Claude to find it when it prepares release notes","Ask developers to paste the whole procedure into the prompt each time they prepare a release"],"a":[0],"x":["a skill's description is always visible but the body loads only when relevant, so the context stays light.","shortening the other rules does not change the fact that a rarely used procedure is always loaded.","Claude has no reason to look in a changelog comment for a procedure it does not know about.","manual pasting is error-prone and wastes effort that a skill avoids."],"e":"Use skills for occasional, detailed procedures; keep CLAUDE.md short and universally relevant."},
{"id":"D3-05","d":3,"t":"s","q":"Scenario: Claude Code workflows. The team wants a shared command that a developer triggers explicitly with an issue number, for example '/fix-issue 123', which then fetches the issue and implements a fix. Where and how should it be defined?","o":["A markdown file in .claude/commands in the repository, using the $ARGUMENTS placeholder for the issue number","A shell alias in each developer's profile that starts Claude Code with a fixed prompt about the issue","A line in CLAUDE.md that says 'when the user types /fix-issue, fetch the issue and fix it'","A hook that runs on every prompt and tries to detect the word 'issue' followed by a number"],"a":[0],"x":["project commands are shared through version control, and the placeholder passes the number given after the command name.","a shell alias runs in the terminal and does not create a command inside Claude Code.","CLAUDE.md can describe behaviour but does not register a command.","a hook on every prompt is fragile and runs for unrelated work."],"e":"Shared, explicitly triggered workflows belong in .claude/commands, with $ARGUMENTS for input."},
{"id":"D3-06","d":3,"t":"s","q":"Scenario: Claude Code workflows. A team wants a security-review helper that reads code and reports findings but must never modify files. It should be used automatically when the user asks for a security check. Which configuration is best?","o":["A subagent definition with a description about security reviews and a tool list restricted to read-only tools","A CLAUDE.md line saying 'be careful not to change files during security reviews', which applies to all sessions","A slash command that includes the sentence 'do not edit anything' and that developers trigger by hand","A subagent with all tools available, whose prompt states strongly that it must never modify any files"],"a":[0],"x":["the description drives delegation, and the tool restriction is enforced by configuration.","guidance in CLAUDE.md can be ignored and is not tied to a specific task.","a sentence in a command is instruction only, and the command has to be triggered manually.","a prompt-only restriction still lets the subagent edit files if it decides to or is misled."],"e":"Restrict tools in the subagent definition to enforce read-only behaviour, and write a clear description for delegation."},
{"id":"D3-07","d":3,"t":"s","q":"Scenario: Claude Code workflows. A developer must replace an authentication library across about 60 files in an unfamiliar codebase. Earlier attempts started editing immediately and produced inconsistent changes. Which approach is best?","o":["Start in plan mode, let Claude explore and propose an approach, review and adjust the plan, and then allow edits","Ask Claude to edit all 60 files in one prompt that says 'be consistent across all of the files'","Run the change in headless mode, so that it cannot be interrupted before all of the files are done","Skip exploration and let Claude start with the files that it considers easiest, to build momentum"],"a":[0],"x":["exploring first and agreeing on an approach avoids inconsistent changes and wasted edits.","a single instruction to be consistent does not give Claude the understanding it needs and offers no checkpoint.","headless mode removes the opportunity to review and correct the approach.","starting with the easiest files delays the real design decisions and invites rework."],"e":"For large changes in unfamiliar code, explore and agree a plan before editing."},
{"id":"D3-08","d":3,"t":"s","q":"Scenario: CI integration. A team wants Claude Code to review each pull request in CI and post a comment. The job runs without a human present. Which setup is most appropriate?","o":["Run it non-interactively with a defined prompt, a narrow tool list, and structured output","Run it in interactive mode and wait for a person to answer the permission prompts as they appear in the log","Disable all permission checks on the CI runner, so that the job can never block on a prompt from the tool","Run it with the maximum set of tools available, in case the review turns out to need any of them later"],"a":[0],"x":["non-interactive runs with a narrow tool list and parseable output suit unattended jobs.","a CI job has nobody to answer prompts, so it would hang.","removing checks gives an unattended process unrestricted access to the runner and its secrets.","maximum tools increase the damage that a prompt injection in the pull request could cause."],"e":"Unattended runs should be non-interactive, narrowly scoped, and produce output that code can parse."},
{"id":"D3-09","d":3,"t":"s","q":"Scenario: Claude Code permissions. A developer wants Claude to run the unit tests freely but never run destructive shell commands or read the production credentials file. Which configuration expresses this?","o":["Allow all Bash commands and trust Claude's judgement to avoid the destructive ones, since it knows the risks well","Allow the test command, deny destructive command patterns and reads of the credentials file, and let others ask","Deny every tool so that nothing can go wrong, and run the unit tests by hand outside of Claude Code itself","Add a CLAUDE.md line telling Claude not to touch the credentials file or run any destructive commands"],"a":[1],"x":["judgement is not a control, and a single mistake can be destructive.","specific allow rules remove friction for safe commands, and deny rules block what must never happen.","this removes the benefit of the assistant entirely.","a guideline can be missed or overridden; a deny rule is enforced."],"e":"Use allow, ask and deny rules to grant exactly what is needed and block what must never happen."},
{"id":"D3-10","d":3,"t":"s","q":"Scenario: Claude Code and MCP. A developer wants to try an experimental MCP server for personal use, while the team uses a shared documentation server in every repository clone. Which scopes fit?","o":["Add both servers to the project scope, so that everybody on the team gets the same tools","Add the experimental server to the user or local scope and the shared documentation server to the project scope","Add both servers to the user scope of each developer, and describe the setup in the team wiki","Add the experimental server to the project scope, so that colleagues can try it and give feedback"],"a":[1],"x":["the experiment would be forced on the whole team, including its permissions and risks.","project scope is shared through the repository and personal scopes stay private to the developer.","the team would have to configure the shared server individually and would drift apart.","colleagues would receive an unreviewed server and its access."],"e":"Use project scope for shared servers and personal scopes for experiments."},
{"id":"D3-11","d":3,"t":"s","q":"Scenario: Claude Code context. In one session a developer fixed a login bug, then started a data-export feature, then asked about CI. Answers are now slower and Claude sometimes applies conventions from the login work to the export feature. What is the best approach?","o":["Keep going in the same session, since it contains all of the background that Claude could need","Clear the context between unrelated tasks, and compact the conversation when a single task runs long","Restart the editor whenever the topic changes, so that the next task begins with a clean slate","Repeat all earlier instructions at the start of every new prompt, so that nothing is forgotten"],"a":[1],"x":["accumulated unrelated context dilutes attention and carries over assumptions that no longer apply.","a clean context for each task keeps it focused, and compaction preserves the thread of one long task.","restarting the editor does not change what is in the conversation context.","repetition adds more to the context and does not remove the stale material."],"e":"Clear context between unrelated tasks and compact within long ones."},
{"id":"D3-12","d":3,"t":"s","q":"Scenario: Claude Code workflows. A developer wants to run two Claude Code sessions at once, one implementing a feature and one fixing an unrelated bug, in the same repository. They keep overwriting each other's changes. What is the best setup?","o":["Use separate git worktrees, with one session in each worktree on its own branch","Run both sessions in the same directory and ask them to commit very often to limit the damage","Clone the repository twice and copy files between the two clones by hand when the work is done","Run the sessions one after the other and avoid parallel work on the repository altogether"],"a":[0],"x":["each session has its own working directory and branch, so edits never collide and branches merge normally.","both sessions still edit the same files on disk, so conflicts persist.","manual copying is error-prone and loses history.","safe but gives up the benefit of parallel work that worktrees allow."],"e":"Use git worktrees to give parallel sessions isolated working directories."},
{"id":"D3-13","d":3,"t":"s","q":"Scenario: Claude Code debugging. A test fails about one run in ten in CI. A developer asks Claude to 'fix the flaky test'. Claude changes the assertion timeout and reports success, but the test still fails sometimes. What should the workflow include?","o":["Ask Claude to delete the flaky test and add a new one with the same name that covers the same behaviour","Have Claude reproduce the failure with repeated runs, form a hypothesis, and verify the fix with repeated runs","Increase the number of automatic retries in CI, so that the intermittent failure no longer blocks any merges","Ask Claude to explain in general why tests become flaky, and apply the most common remedy that it names"],"a":[1],"x":["this removes coverage without understanding the cause.","evidence from reproduction guides a targeted fix, and repeated runs show whether it worked.","retries mask the problem and do not fix it.","general knowledge about flakiness does not identify the cause in this test."],"e":"Reproduce, observe, hypothesise and verify; do not accept a fix without evidence that the failure is gone."},
{"id":"D3-14","d":3,"t":"s","q":"Scenario: Claude Code workflows. Claude has written a database migration that renames a column used by three services. Which sequence is the safest before it reaches production?","o":["Run it directly on production during low-traffic hours and monitor the services closely while it runs","Run it on a staging copy with realistic data, review the SQL and affected queries, run tests, and prepare a rollback","Merge it and rely on the three services to adapt to the new column name when they fail","Ask Claude to confirm in its summary that the migration is safe, and attach the summary to the pull request"],"a":[1],"x":["an irreversible change on production without rehearsal risks an outage.","rehearsal on realistic data, review and a rollback plan reduce the risk of an irreversible failure.","services will fail at runtime, which turns a controllable change into an incident.","the model's statement is not evidence of safety."],"e":"Rehearse high-impact changes and keep a rollback path; do not accept a summary as verification."},
{"id":"D3-15","d":3,"t":"m","q":"Scenario: Claude Code instructions. A CLAUDE.md has grown to 900 lines. Developers notice that important rules are sometimes ignored. Which TWO changes are most likely to help? (Select 2)","o":["Remove reference material and one-off notes, and keep short, specific and actionable rules","Move rarely needed procedures into skills or commands that load only when relevant","Add more explanatory paragraphs so that Claude understands the reasoning in depth","Repeat all rules in every section so none can be missed","Translate the file to several languages so that it is robust"],"a":[0,1],"x":["a leaner file puts the important rules in focus and removes noise.","occasional procedures stop competing for attention in every session.","more text adds to the problem; length dilutes the rules that matter.","repetition makes the file longer without making any rule clearer.","translations add length and do not improve compliance."],"e":"Keep CLAUDE.md short and universally relevant; move occasional material elsewhere."},
{"id":"D3-16","d":3,"t":"s","q":"Scenario: Claude Code in an organisation. A platform team has built commands, hooks, a subagent and an MCP configuration that 30 repositories should share, with versioned updates. What is the best way to distribute them?","o":["Package them as a plugin and distribute it through a shared marketplace","Copy the files into each repository and tell the teams to update them by hand when something changes","Send the files by e-mail and ask each team to install them in the way that suits that team","Put all of the instructions into the root CLAUDE.md of each repository and keep a copy in the wiki"],"a":[0],"x":["a plugin bundles the components and gives one place to publish and update them.","manual copying leads to drift and stale versions across 30 repositories.","e-mail distribution has no versioning and no update path.","CLAUDE.md holds instructions and does not install commands, hooks, subagents or servers."],"e":"Use plugins to distribute and version bundles of commands, hooks, agents and server configuration."},
{"id":"D3-17","d":3,"t":"s","q":"Scenario: Claude Code onboarding. A new repository has no Claude Code configuration. What is a sensible first step?","o":["Write a 500-line CLAUDE.md by hand before the first session, covering every convention that anyone can think of","Use /init to generate a starting CLAUDE.md from the codebase, then review and trim it","Copy the CLAUDE.md from an unrelated project that has a similar technology stack, and adapt it later","Start without any file and add instructions only when problems appear during the sessions"],"a":[1],"x":["a large first draft is likely to contain guesses and noise.","the generated draft captures commands and structure, and the team refines it into accurate, concise guidance.","another project's rules describe a different codebase and will mislead.","avoids early effort but sessions begin without build and test commands and the project conventions."],"e":"Generate a draft with /init, then review and refine it."},
{"id":"D3-18","d":3,"t":"s","q":"Scenario: Claude Code safety. The team wants to make sure no session ever force-pushes to the main branch, even when a developer has approved a broad set of shell commands. Which mechanism is most reliable?","o":["A PreToolUse hook that inspects Bash commands and blocks any force-push to the main branch","A CLAUDE.md line saying 'never force-push to main', which every session loads at the start","A note in the contributing guide that explains the branch policy and the reasons behind it","Ask developers to watch the terminal and to interrupt Claude if they see a push command start"],"a":[0],"x":["the hook runs before the command and can block it deterministically, whatever was approved earlier.","a guideline can be ignored or overridden by other instructions.","documentation does not influence a running session.","manual vigilance is unreliable and does not scale."],"e":"Block must-never-happen commands with a pre-tool hook, not with guidance."},
{"id":"D3-19","d":3,"t":"s","q":"Scenario: Claude Code workflows. A developer asks Claude to implement a pricing-rule module. Earlier attempts passed the code review but failed in production edge cases. Which workflow most improves reliability?","o":["Ask Claude to write tests for the specified edge cases first, confirm that they fail, then implement until they pass","Ask Claude to write the module and then to explain in detail why the implementation is correct","Have Claude implement the module with as few lines of code as possible, which reduces the risk of bugs","Let Claude choose the edge cases after it has finished the implementation, since it knows the code best"],"a":[0],"x":["tests written from the specification give an objective target, and the loop shows when the work is done.","an explanation is not verification and may repeat the same mistaken assumptions.","brevity is unrelated to correctness for edge cases.","edge cases chosen after the fact tend to match what the code already does."],"e":"Give Claude an objective check, such as tests defined in advance, to iterate against."},
{"id":"D3-20","d":3,"t":"s","q":"Scenario: Claude Code instructions. The team's API conventions live in docs/api-style.md, which several services reference. Developers want Claude to follow them without copying the text into every CLAUDE.md. What is the best approach?","o":["Copy the file contents into every CLAUDE.md and update the copies by hand whenever the document changes","Reference the file from CLAUDE.md with an import, so that a single source of truth is loaded","Tell developers to paste the file into the first prompt of each session, before they start any task","Rename the file to CLAUDE.md in the docs folder, so that all services load it automatically"],"a":[1],"x":["copies drift apart as soon as one is changed.","an import keeps one maintained document and includes it where needed.","manual pasting is inconsistent and easy to forget.","a file in docs is loaded only in the context of that directory, not as shared guidance for all services."],"e":"Import shared documents from CLAUDE.md instead of copying them."},
{"id":"D3-21","d":3,"t":"s","q":"Scenario: Claude Code in an enterprise. Security requires that certain tools are always denied and that a particular MCP server is never used, for every employee, regardless of their own settings. Where should this be configured?","o":["Configure them in each developer's user settings file, and verify compliance through an onboarding checklist","Configure them in the managed policy settings that the organisation deploys to every machine","Configure them in the shared project settings file, because developers cannot edit that file at all","Describe them on a company wiki page that every new employee has to read and acknowledge"],"a":[1],"x":["user settings can be changed by the user, and the checklist depends on compliance.","managed settings are deployed by the organisation and take precedence over user and project settings.","project settings apply only to that repository and can be overridden locally.","a wiki page documents a policy but does not enforce it."],"e":"Organisation-wide mandatory controls belong in managed policy settings."},
{"id":"D3-22","d":3,"t":"s","q":"Scenario: Claude Code workflows. Developers complain that Claude often declares a task finished while the test suite is red. The team wants Claude to check the tests before it stops. Which mechanism enforces this best?","o":["A Stop hook that runs the tests and, if they fail, returns the output so that Claude continues working","A reminder in CLAUDE.md to run the tests before declaring any task finished, in the section on workflow","A pre-commit hook in git that runs the tests when a developer commits the changes","A comment at the top of the main test file that explains how and when the suite should be run"],"a":[0],"x":["the hook runs when Claude would stop and can send it back to work with the failure output.","guidance may be forgotten, especially late in a long session.","this catches problems only at commit time, after Claude has reported the task as finished.","comments in test files are not read as instructions."],"e":"Use lifecycle hooks to enforce checks at the moment they matter, such as before Claude stops."},
{"id":"D3-23","d":3,"t":"s","q":"Scenario: CI integration. A pipeline step uses Claude Code to classify failing builds. The next step must read the classification and decide whether to notify a team. Currently the step parses prose output with a regular expression and breaks whenever the wording changes. What is the best improvement?","o":["Ask for more consistent wording in the prompt and keep the regular expression that reads the classification","Request structured (JSON) output from the non-interactive run, with a schema in the prompt, and parse it","Pass the prose output to the next step and let a person read it and decide about the notification","Run the classification three times and take the wording that appears most often as the result"],"a":[1],"x":["wording will still vary and the parser stays fragile.","structured output gives the next step a parseable contract instead of depending on phrasing.","this removes automation from the pipeline.","repetition triples the cost and does not remove the parsing problem."],"e":"Automation needs structured output with a defined contract, not parsing of prose."},
{"id":"D3-24","d":3,"t":"m","q":"Scenario: Claude Code workflows. A pull request touches 120 files across four services. A single review session fills its context and misses issues. Which TWO approaches improve the review? (Select 2)","o":["Use subagents to review each service in parallel, each returning a concise findings summary","Have the main session read all 120 files first so that it has the complete picture","Split the review into focused passes, for example security, then API changes, then tests","Ask for a quick overall opinion and skip detailed review to save context","Paste the diff into the prompt as one large message without file boundaries"],"a":[0,2],"x":["parallel subagents keep the main context clean and each one can concentrate on its own area.","reading everything first exhausts context before analysis starts.","focused passes let each analysis concentrate on one concern instead of everything at once.","a shallow overall opinion misses the details that review is for.","a single unstructured block makes it harder to attribute findings and wastes context."],"e":"Split large reviews across subagents or focused passes to keep context manageable and analysis sharp."},
{"id":"D3-25","d":3,"t":"s","q":"Scenario: CI integration. A nightly Claude Code job needs to run the project's test command and open a draft pull request, but the job keeps pausing for permission. A colleague suggests running it with all permission checks disabled. What is the better solution?","o":["Disable all permission checks, since the runner is a throwaway machine that is destroyed after each run","Pre-approve only the specific commands the job needs and deny everything else","Let the job pause at each prompt, and have a developer approve the steps the next morning","Run the job on a developer laptop under the developer's full account, so that permissions are never a problem"],"a":[1],"x":["the runner still has repository access and credentials, and a prompt injection could misuse unrestricted permissions.","an explicit allowlist keeps the job automatic while limiting what it can do.","a paused job defeats the purpose of an unattended run.","a developer's full account raises the blast radius considerably."],"e":"Unattended runs should use a narrow allowlist, not blanket permission bypass."},
{"id":"D3-26","d":3,"t":"s","q":"Scenario: Claude Code workflows. A developer asks Claude to understand how authentication works in a 2-million-line repository, and then reference every file in the auth directory in the prompt. The session becomes slow, and answers get vague. What is a better approach?","o":["Reference the whole repository in the prompt, so that nothing relevant to authentication is missed by Claude","Let Claude search for entry points, or delegate exploration to a subagent that returns a summary with references","Ask Claude to read all files alphabetically until it finds the code that deals with authentication in the system","Split the repository across several sessions and ask each of them the same question about authentication"],"a":[1],"x":["more files in the prompt increase noise and fill the context without improving focus.","targeted search finds what matters, and a subagent keeps the raw exploration out of the main session.","alphabetical reading is inefficient and fills the context with irrelevant code.","repeating the question in several sessions multiplies cost without synthesising the result."],"e":"Explore large codebases through targeted search and delegated exploration, not by loading everything."},
{"id":"D3-27","d":3,"t":"m","q":"Scenario: Claude Code instructions. Developers report that rules in CLAUDE.md such as 'write clean code' and 'be careful with the database' are not followed consistently. Which TWO rewrites make the instructions more effective? (Select 2)","o":["Replace vague phrases with specific, verifiable rules, such as 'use parameterised queries; never build SQL by concatenation'","Add the exact commands for build, test and lint so that the assistant can verify its own work","Add motivational statements such as 'you are an excellent engineer'","Repeat the vague rules three times at the end of the file","Add a paragraph on the history of the project"],"a":[0,1],"x":["specific rules can be applied and checked, which vague preferences cannot.","commands give Claude a way to check results, which improves reliability.","motivation does not tell Claude what to do.","repetition adds length without adding precision.","history does not help Claude apply the rules."],"e":"Write specific, verifiable instructions and give the commands needed to check the work."},
{"id":"D3-28","d":3,"t":"s","q":"Scenario: Claude Code workflows. Midway through a refactor Claude starts rewriting modules the developer did not ask about. What is the best response?","o":["Let it finish and clean up afterwards, since it is already well on the way through the whole refactor","Interrupt, restate the scope, and restore unwanted changes from version control before continuing","Ask Claude to continue but to be more careful about which modules it chooses to modify from now on","Close the session and start the task again from scratch, without saving any of the earlier work done"],"a":[1],"x":["unwanted changes make the final diff larger and harder to review.","stopping early limits the damage, and a clear scope plus a restore point returns the work to a known state.","a vague request for care does not restore the scope and leaves the unwanted changes in place.","discarding everything wastes the useful work that was done earlier."],"e":"Interrupt early, restate the scope, and use version control to return to a known state."},
{"id":"D3-29","d":3,"t":"s","q":"Scenario: Claude Code workflows. Claude implemented a feature in a long session, and the developer wants a thorough review before merging. Which approach most likely finds problems that Claude missed while writing?","o":["Ask the same session 'is this correct?' and accept the answer that it gives after rereading its work","Start a fresh session or reviewer subagent, give it the diff and requirements, and have it review independently","Ask Claude to re-read the code once more in the same session, this time with a stricter attitude","Skip the review, since all of the tests passed and the implementation follows the specification"],"a":[1],"x":["the session carries the assumptions that produced the code, so it tends to confirm them.","an independent context does not share the author's reasoning and is more likely to notice what it overlooked.","re-reading in the same context repeats the same blind spots.","passing tests show that tested behaviour works, not that the design and the untested paths are sound."],"e":"Use an independent context for review so that it does not inherit the author's assumptions."},
{"id":"D3-30","d":3,"t":"s","q":"Scenario: Claude Code safety. A project has a .env file with production credentials in the repository directory. The team wants to be sure that Claude cannot read it during any session, even if a developer asks for broad file access. Which configuration is most reliable?","o":["Add a deny rule for reading the .env file in the project's shared settings","Add a line 'do not read .env' to CLAUDE.md, which every session loads at the start","Rename the file to .env.old, so that tools that look for .env no longer find it","Ask developers to avoid mentioning the file in prompts, so that Claude has no reason to open it"],"a":[0],"x":["a deny rule is enforced by the tool and is shared with the team through the repository.","a guideline can be overridden or forgotten and is not enforced.","renaming only hides the file from conventions, and Claude can still find and read it.","requests do not control what Claude searches or reads."],"e":"Protect secrets with enforced deny rules and keep them out of reach rather than relying on instructions."}
]);
